function solve(r, c1, c2) {
  if (r == rows) return 0;
  let res = grid[r][c1] + (c1 == c2 ? 0 : grid[r][c2]);
  let maxNext = 0;
  for (let nextC1 = c1 - 1; nextC1 <= c1 + 1; nextC1++) {
    for (let nextC2 = c2 - 1; nextC2 <= c2 + 1; nextC2++) {
      maxNext = Math.max(maxNext, solve(r + 1, nextC1, nextC2));
    }
  }
  return res + maxNext;
}
